int main(int argc,char**argv){if(argc!=2)throw std::runtime_error("caseset");std::string set=argv[1];cudaDeviceProp prop;C(cudaGetDeviceProperties(&prop,0));int blocks=2*prop.multiProcessorCount;if(blocks!=160)throw std::runtime_error("predeclaredV10080SM");int occ1,occ2;C(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&occ1,MPCcompress,1024,0));C(cudaOccupancyMaxActiveBlocksPerMultiprocessor(&occ2,MPCdecompress,1024,0));if(occ1<2||occ2<2)throw std::runtime_error("residencyguard");for(int trial=0;trial<=5;trial++){std::ifstream cases("cases_"+set+".txt");if(!cases)throw std::runtime_error("missingcases");int index,n,dim,cap,used,consumed,ncases=0;double compress=0,decompress=0;std::vector<B>pre,out,expectedpre,expectedout;while(cases>>index>>n>>dim>>cap>>used>>consumed){std::string dir="fixtures/"+set+"/case"+std::to_string(index)+"/";auto input=readall(dir+"input_u64.bin"),ec=readall(dir+"encoded_u64.bin"),di=readall(dir+"decoder_input_u64.bin"),ed=readall(dir+"decoded_u64.bin"),oc=readall(dir+"offset_comp_i32.bin"),od=readall(dir+"offset_dec_i32.bin");if(input.size()!=size_t(n)*8||ec.size()!=size_t(cap)*8||di.size()!=ec.size()||ed.size()!=input.size()||oc.size()!=640||od.size()!=640)throw std::runtime_error("fixtureextent");Buf I(input.size(),input.data()),E(ec.size()),D(ed.size()),O(640,nullptr,255);auto ipre=I.all();append(pre,ipre);append(expectedpre,guarded(input));C(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();C(cudaMemset(O.ptr<int>(),255,640));MPCcompress<<<blocks,1024>>>(n,I.ptr<long>(),E.ptr<long>(),O.ptr<int>(),dim);C(cudaGetLastError());C(cudaDeviceSynchronize());compress+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count();auto encoded=E.all(),co=O.all();append(out,encoded);append(expectedout,guarded(ec));if(encoded!=guarded(ec)||co!=guarded(oc)||I.all()!=ipre)throw std::runtime_error("compression_fullbitcheck_case"+std::to_string(index));uint64_t header=(uint64_t(n)<<32)+0x43504cffULL+dim;C(cudaMemcpy(E.ptr<lon